"use strict";(self.webpackChunkstarmade_guides=self.webpackChunkstarmade_guides||[]).push([[6092],{5264(e,i,t){t.r(i),t.d(i,{assets:()=>d,contentTitle:()=>o,default:()=>l,frontMatter:()=>r,metadata:()=>s,toc:()=>h});const s=JSON.parse('{"id":"building/shipyards","title":"Shipyards","description":"Shipyards are Space Station based systems that allow players to design ships in a temporary virtual creative environment and mass produce those designs from a loaded design, which is similar to a blueprint. You can also dock an existing ship into a shipyard to completely deconstruct it, or repair it using an existing loaded design.","source":"@site/docs/01-building/03-shipyards.md","sourceDirName":"01-building","slug":"/building/shipyards","permalink":"/StarMade-Guides/pre/building/shipyards","draft":false,"unlisted":false,"editUrl":"https://github.com/StarMade-Community/StarMade-Guides/edit/pre/docs/01-building/03-shipyards.md","tags":[],"version":"current","sidebarPosition":3,"frontMatter":{},"sidebar":"defaultSidebar","previous":{"title":"Docking & Turrets","permalink":"/StarMade-Guides/pre/building/docking-and-turrets"},"next":{"title":"Ship Basics","permalink":"/StarMade-Guides/pre/ships/ship-basics"}}');var a=t(4848),n=t(8453);const r={},o="Shipyards",d={},h=[{value:"Construction",id:"construction",level:2},{value:"Docking An Existing Ship",id:"docking-an-existing-ship",level:2},{value:"Ship Designs",id:"ship-designs",level:2},{value:"Test Sector",id:"test-sector",level:2},{value:"Mass Production",id:"mass-production",level:2},{value:"Repairing Ships",id:"repairing-ships",level:2},{value:"Deconstructing Ships",id:"deconstructing-ships",level:2}];function c(e){const i={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,n.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(i.header,{children:(0,a.jsx)(i.h1,{id:"shipyards",children:"Shipyards"})}),"\n",(0,a.jsxs)(i.p,{children:["Shipyards are Space Station based systems that allow players to design ships in a temporary virtual creative environment and mass produce those designs from a loaded design, which is similar to a ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/multiplayer/catalog-and-blueprints",children:"blueprint"}),". You can also dock an existing ship into a shipyard to completely deconstruct it, or repair it using an existing ",(0,a.jsx)(i.em,{children:"loaded"})," design."]}),"\n",(0,a.jsx)(i.h2,{id:"construction",children:"Construction"}),"\n",(0,a.jsxs)(i.p,{children:["Shipyards are constructed from a Shipyard Computer, Shipyard Modules, and a Shipyard Core Anchor. The computer, as with any other ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/logic/logic-basics#connecting-to-weapon-computers",children:"system computer"}),", must have all of the Shipyard Modules ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/logic/logic-basics#connecting-blocks",children:"connected"}),' to it, as well as the Shipyard Core Anchor. A shipyard is only valid if the Shipyard Modules form a C shape, with both "ends" of the C being straight across from each other. A player can build as many or as few C-shaped sections as they want without affecting the function of a shipyard, provided that they are lined up. It should look ',(0,a.jsx)(i.a,{href:"https://starmadedock.net/content/3210",children:"something like this"}),". The Shipyard Core Anchor can be placed anywhere within the perimeter of a Shipyard, but it is important that there are no solid blocks near it and that it is sufficiently spaced from the edges of the Shipyard to allow space for ships to take up. Note that wherever you place the Shipyard Core Anchor is where the actual ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/ships/building-a-ship#spawning-a-ship-core",children:"Ship Core"})," will appear. Ship designs will fail to load into the Shipyard Computer if there is not enough space inside the Shipyard Modules area for the ship."]}),"\n",(0,a.jsx)(i.h2,{id:"docking-an-existing-ship",children:"Docking An Existing Ship"}),"\n",(0,a.jsxs)(i.p,{children:["Ships can ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/building/docking-and-turrets#docking-a-ship",children:"dock"})," to a Shipyard Core Anchor as they would with any other ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/building/docking-and-turrets#rail-blocks",children:"Rail"}),". If they do not have a Rail Docker, the Activation Beam from a core or camera can be used to connect with the Anchor. Either way, the ship is docked with the Ship Core at the position of the Shipyard Core Anchor. The Ship Core is ",(0,a.jsx)(i.strong,{children:"always"})," docked in alignment to the Shipyard Core Anchor."]}),"\n",(0,a.jsx)(i.h2,{id:"ship-designs",children:"Ship Designs"}),"\n",(0,a.jsxs)(i.p,{children:["Shipyards use a special type of item called 'Designs' to function. They are similar to blueprints, and can be interchanged with blueprints through the Shipyard Computer. To create a new ship, use the ",(0,a.jsx)(i.strong,{children:"Create New Design"})," function in the Shipyard Computer. This will create a blank design with a virtual Ship Core at the position of the Shipyard Core Anchor. Blocks cannot be placed on the virtual ship except in build mode. The virtual ship is almost identical in function to a normal ship, except for a few important aspects:"]}),"\n",(0,a.jsxs)(i.ul,{children:["\n",(0,a.jsx)(i.li,{children:"The virtual ship cannot be edited except in the Shipyard's build mode."}),"\n",(0,a.jsxs)(i.li,{children:["The virtual ship cannot be undocked (however, use of Flight Mode without undocking is permitted, e.g. to test ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/logic/logic-basics",children:"logic"}),")"]}),"\n",(0,a.jsx)(i.li,{children:"The virtual ship has a hologram-styled shader applied to all of its blocks outside of the Shipyard's build mode."}),"\n",(0,a.jsx)(i.li,{children:"When editing the virtual ship, regardless of permissions, the player uses a Creative Mode inventory."}),"\n",(0,a.jsx)(i.li,{children:"Using blocks from a linked cargo in your inventory will not actually consume materials, rather behaving like creative mode."}),"\n"]}),"\n",(0,a.jsx)(i.h2,{id:"test-sector",children:"Test Sector"}),"\n",(0,a.jsxs)(i.p,{children:["The Test Sector is a virtual space in which a Design can be tested. Although it would seem to be a special ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/world/navigation#sectors",children:"Sector"}),", it is not. It takes its surroundings from a specific location in ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/world/navigation#systems",children:"System"})," 0,0,0. As such, if there is a Pirate Station near that specific sector, it can cause problems when testing designs. Nominally, there would be no Pirate Stations present, and the player would be able to spawn in enemies of their choosing to fight or spawn static armored/shielded targets to test weapons on their design."]}),"\n",(0,a.jsxs)(i.p,{children:["It should be noted that, although it is assured that use of the Test Sector imparts no penalty on the player, death while in the Test Sector results in respawning at the player's ",(0,a.jsx)(i.em,{children:"most recently-activated"})," Undeathinator. This can be problematic for some players who forgot to set their spawn point at their far-out base."]}),"\n",(0,a.jsx)(i.h2,{id:"mass-production",children:"Mass Production"}),"\n",(0,a.jsx)(i.p,{children:"Assuming that all the necessary materials to construct a loaded ship design is present in the Shipyard Computer's inventory (which can be expanded with the use of Cargo), ships can be constructed, undocked, and reconstructed quickly. The Shipyard will, regardless of size, place up to 2,500 blocks per tick, meaning that a ship would have to be massive to take more than a couple minutes to be fully constructed with enough materials. Most small ships, such as drones, take only a few seconds to be constructed. In the Shipyard Computer, there is an option to undock the newly-constructed ship, so that all you have to do is move the new ship out of the way before re-loading and constructing the design again. When used properly, Shipyards can produce entire fleets of AI-controlled ships rapidly."}),"\n",(0,a.jsx)(i.h2,{id:"repairing-ships",children:"Repairing Ships"}),"\n",(0,a.jsxs)(i.p,{children:["Shipyards can also be used to repair damaged ships or update mass-produced ships to a new standard design. This is done through a function of the Shipyard Computer, which basically deconstructs the ship and reconstructs it according to the ",(0,a.jsx)(i.em,{children:"loaded"})," design. This design does not have to bear any resemblance to the original ship. Note that, since repairing completely deconstructs the ship and rebuilds it, it resets any saved hotbar configurations. A less destructive Ship repairing solution would be to use an ",(0,a.jsx)(i.a,{href:"/StarMade-Guides/pre/ships/weapons-and-effects#astrotech-beam",children:"Atrotech Beam"})," instead."]}),"\n",(0,a.jsx)(i.h2,{id:"deconstructing-ships",children:"Deconstructing Ships"}),"\n",(0,a.jsx)(i.p,{children:"The Shipyard Computer can be used to deconstruct a docked ship and save it to a design, or simply deconstruct it without saving any design. This can be used to rapidly disassemble unused AI fleets or drones."})]})}function l(e={}){const{wrapper:i}={...(0,n.R)(),...e.components};return i?(0,a.jsx)(i,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},8453(e,i,t){t.d(i,{R:()=>r,x:()=>o});var s=t(6540);const a={},n=s.createContext(a);function r(e){const i=s.useContext(n);return s.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function o(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),s.createElement(n.Provider,{value:i},e.children)}}}]);